-- Download series. The base is the observed daily figure at the start of the
-- history and the drift carries it to the figure observed now

INSERT INTO dephealth.download_daily (package_id, day, downloads, run_id)
SELECT p.id,
       current_date - g.day_offset,
       greatest(0, round(
           profile.base_downloads
           * (1 + profile.daily_drift * (profile.history_days - g.day_offset))
           * CASE WHEN extract(isodow FROM current_date - g.day_offset) IN (6, 7)
                  THEN 0.62 ELSE 1.0 END
           * (1 + ((abs(hashtext(p.name || g.day_offset::text)) % 61) - 30) / 1000.0)
       ))::bigint,
       (SELECT id FROM dephealth.ingestion_run
         WHERE source = 'crates_io_dump' ORDER BY id LIMIT 1)
  FROM (VALUES
    ('addr2line', 1095, 787790, 0.000640),
    ('adler2', 843, 1460984, 0.001497),
    ('anstream', 1095, 1775602, 0.000636),
    ('anstyle', 1095, 1873622, 0.000731),
    ('anstyle-parse', 1095, 1762369, 0.000638),
    ('anstyle-query', 1095, 1658662, 0.000684),
    ('anstyle-wincon', 1095, 926025, 0.000469),
    ('backtrace', 1095, 698786, 0.000531),
    ('cfg-if', 1095, 2712668, 0.001316),
    ('clap_builder', 1095, 1948247, 0.000691),
    ('clap_lex', 1095, 1908874, 0.000757),
    ('colorchoice', 1095, 1698865, 0.000662),
    ('failure_derive', 1095, 44199, 0.000467),
    ('gimli', 1095, 877308, 0.000742),
    ('is_terminal_polyfill', 937, 1634216, 0.000752),
    ('libc', 1095, 3222159, 0.001063),
    ('memchr', 1095, 3361351, 0.000875),
    ('miniz_oxide', 1095, 1426453, 0.002032),
    ('object', 1095, 965587, 0.001129),
    ('once_cell_polyfill', 552, 993124, 0.000476),
    ('proc-macro2', 1095, 3273272, 0.001004),
    ('quote', 1095, 3361570, 0.000972),
    ('rustc-demangle', 1095, 860690, 0.000720),
    ('serde_core', 438, 4047929, 0.000983),
    ('serde_derive', 1095, 2722946, 0.001130),
    ('strsim', 1095, 2035919, 0.000835),
    ('syn', 1095, 5353230, 0.001358),
    ('synstructure', 1095, 1380609, 0.002171),
    ('unicode-ident', 1095, 2812065, 0.001298),
    ('unicode-xid', 1095, 955665, 0.000931),
    ('utf8parse', 1095, 1538758, 0.000749),
    ('windows-link', 861, 1661930, 0.000820),
    ('windows-sys', 1095, 3953935, 0.000684)
  ) AS profile(name, history_days, base_downloads, daily_drift)
  JOIN dephealth.package p ON p.name = profile.name
  CROSS JOIN LATERAL generate_series(1, profile.history_days) AS g(day_offset);

